"""
UConn Library Partner Map — Shiny for Python dashboard

Run with:
    pip install shiny folium pandas
    shiny run --reload app.py

Static version (runs in the browser, e.g. on GitHub Pages): see build_static.sh

Expects geo_partnerdata.csv in the same folder as this script.
The loader auto-detects the columns, so it works whether the CSV has
  - a WKT geometry column, e.g.  geometry = "POINT (-72.25 41.80)"   (what gdf.to_csv() writes)
  - or separate latitude / longitude columns
Adjust the CONFIG block below if the column names are unusual.
"""

from pathlib import Path
import math

import folium
from branca.element import MacroElement
from folium.plugins import MarkerCluster
from jinja2 import Template
import pandas as pd
from shiny import App, reactive, render, ui

# ----------------------------------------------------------------------------
# CONFIG
# ----------------------------------------------------------------------------
DATA_FILE = Path(__file__).parent / "geo_partnerdata.csv"

# Set these to the exact column names, or leave as None to auto-detect.
NAME_COL = None      # e.g. "library_name"
COUNTRY_COL = None   # e.g. "country"
GEOM_COL = None      # e.g. "geometry" (WKT points)
LAT_COL = None       # used only if there is no WKT geometry column
LON_COL = None

HUB_NAME = "UConn Storrs"
HUB_LAT, HUB_LON = 41.8077, -72.2540   # UConn Storrs campus

UCONN_NAVY = "#2D66E9"
FLOW_COLOR = "#CD5C5C"   # indian red
FLOW_OPACITY = 0.35      # transparent, so overlapping flows build up density
POINT_COLOR = "#E33939"  # UConn red, used sparingly for partner points

# Seaborn "mako", light -> dark; clusters with more libraries get darker colors
MAKO = ['#a9e1bd', '#60ceac', '#3eb4ad', '#3497a9', '#357aa2',
        '#395d9c', '#413f80', '#382a54', '#251729']  # sns.color_palette("mako_r", 9)

# Country (as spelled in the CSV) -> continent. Anything not listed shows as "Other".
CONTINENTS = {
    "North America": ["USA", "Canada", "Mexico", "PuertoRico"],
    "South America": ["Argentina", "Chile", "Colombia"],
    "Europe": ["England", "Scotland", "Wales", "NorthernIreland", "Ireland", "France", "Germany",
               "Spain", "Italy", "Netherlands", "Belgium", "Switzerland", "Austria", "Denmark",
               "Sweden", "Norway", "Hungary", "Croatia", "Slovenia", "CzechRepublic"],
    "Asia": ["China", "Japan", "SouthKorea", "Taiwan", "Macau", "Singapore", "Indonesia",
             "Thailand", "Israel", "Lebanon", "Bahrain", "Turkey"],
    "Africa": ["Egypt", "SouthAfrica"],
    "Oceania": ["Australia", "NewZealand", "Tasmania", "Queensland"],
}
COUNTRY_TO_CONTINENT = {c: cont for cont, cs in CONTINENTS.items() for c in cs}

# The map is centered on Storrs: its left/right edge is the meridian opposite
# Storrs (~107.75°E). A shortest path from Storrs never crosses that meridian,
# so every radial flow is one unbroken arc. Places east of it (Japan, Korea,
# eastern China, Australia, NZ) are drawn one world-width to the west.
CUT_LON = HUB_LON + 180


def to_map_lon(lon):
    """Shift a longitude into the Storrs-centered window [CUT_LON - 360, CUT_LON)."""
    return (lon - CUT_LON) % 360 + CUT_LON - 360


# Single world copy: Web Mercator tops out at ~±85.05°
WORLD_BOUNDS = [[-85.05, CUT_LON - 360], [85.05, CUT_LON]]


# ----------------------------------------------------------------------------
# DATA LOADING
# ----------------------------------------------------------------------------
def _find(cols, candidates):
    lower = {c.lower().strip(): c for c in cols}
    for cand in candidates:
        if cand in lower:
            return lower[cand]
    # partial match fallback
    for cand in candidates:
        for lc, orig in lower.items():
            if cand in lc:
                return orig
    return None


POINT_RE = r"POINT\s*\(\s*([-+0-9.eE]+)\s+([-+0-9.eE]+)\s*\)"


def load_partners(path: Path) -> pd.DataFrame:
    df = pd.read_csv(path)
    cols = df.columns

    name_col = NAME_COL or _find(cols, ["library_name", "library", "name", "institution", "partner"])
    country_col = COUNTRY_COL or _find(cols, ["country", "nation", "country_name"])
    geom_col = GEOM_COL or _find(cols, ["geometry", "geom", "geo_point", "location", "point", "wkt"])

    # Pure pandas (no geopandas/shapely) so the app also runs in the browser via Shinylive
    if geom_col and df[geom_col].astype(str).str.upper().str.startswith("POINT").any():
        xy = df[geom_col].astype(str).str.extract(POINT_RE).astype(float)   # WKT is "POINT (lon lat)"
        lon, lat = xy[0], xy[1]
    else:
        lat_col = LAT_COL or _find(cols, ["latitude", "lat", "y"])
        lon_col = LON_COL or _find(cols, ["longitude", "lon", "lng", "long", "x"])
        if not (lat_col and lon_col):
            raise ValueError(
                f"Couldn't find a WKT geometry column or lat/lon columns in {list(cols)}. "
                "Set GEOM_COL or LAT_COL/LON_COL in the CONFIG block."
            )
        lat, lon = pd.to_numeric(df[lat_col], errors="coerce"), pd.to_numeric(df[lon_col], errors="coerce")

    gdf = df.assign(lat_=lat, lon_=lon).dropna(subset=["lat_", "lon_"]).copy()

    gdf["name_"] = gdf[name_col].astype(str) if name_col else [f"Partner {i+1}" for i in range(len(gdf))]
    if country_col:
        country = gdf[country_col]
        # Rows with a blank country but a state/province are US libraries in this dataset
        state_col = _find(cols, ["stateorprovince", "state", "province"])
        if state_col:
            country = country.where(country.notna() | gdf[state_col].isna(), "USA")
        gdf["country_"] = country.fillna("Unknown").astype(str)
    else:
        gdf["country_"] = "Unknown"
    gdf["continent_"] = gdf["country_"].map(COUNTRY_TO_CONTINENT).fillna("Other")
    gdf["lon_"] = gdf["lon_"].map(to_map_lon)
    return gdf.reset_index(drop=True)


partners = load_partners(DATA_FILE)
COUNTRIES = sorted(partners["country_"].unique())
CONTINENT_CHOICES = [c for c in [*CONTINENTS, "Other"] if c in set(partners["continent_"])]
# Country dropdown grouped by continent: {continent: {country: country}}
COUNTRY_CHOICES = {
    cont: {c: c for c in sorted(partners.loc[partners["continent_"] == cont, "country_"].unique())}
    for cont in CONTINENT_CHOICES
}


# ----------------------------------------------------------------------------
# GEOMETRY HELPERS
# ----------------------------------------------------------------------------
def great_circle(lat1, lon1, lat2, lon2, n=64):
    """Points along the great-circle arc between two coordinates, in the
    Storrs-centered longitude window. Arcs from Storrs never cross the window's
    edge; the split below only guards against arcs between other points."""
    p1, l1, p2, l2 = map(math.radians, (lat1, lon1, lat2, lon2))
    d = 2 * math.asin(math.sqrt(
        math.sin((p2 - p1) / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin((l2 - l1) / 2) ** 2
    ))
    if d == 0:
        return [[[lat1, lon1], [lat2, lon2]]]

    pts = []
    for i in range(n + 1):
        f = i / n
        a = math.sin((1 - f) * d) / math.sin(d)
        b = math.sin(f * d) / math.sin(d)
        x = a * math.cos(p1) * math.cos(l1) + b * math.cos(p2) * math.cos(l2)
        y = a * math.cos(p1) * math.sin(l1) + b * math.cos(p2) * math.sin(l2)
        z = a * math.sin(p1) + b * math.sin(p2)
        pts.append([math.degrees(math.atan2(z, math.hypot(x, y))), to_map_lon(math.degrees(math.atan2(y, x)))])

    segments, current = [], [pts[0]]
    for prev, cur in zip(pts, pts[1:]):
        if abs(cur[1] - prev[1]) > 180:   # crossed the map edge
            segments.append(current)
            current = []
        current.append(cur)
    segments.append(current)
    return segments


def cluster_icon_js(max_count):
    """Leaflet.markercluster icon function: color on a log scale over MAKO,
    so the largest clusters are darkest; the bubble also grows with count."""
    return f"""
    function(cluster) {{
        var colors = {MAKO};
        var n = cluster.getChildCount();
        var t = Math.log(n) / Math.log(Math.max({max_count}, 2));
        t = Math.min(Math.max(t, 0), 1);
        var i = Math.round(t * (colors.length - 1));
        var size = Math.round(28 + 22 * t);
        var text = i >= colors.length / 2 ? '#ffffff' : '#0b0405';
        return L.divIcon({{
            html: '<div style="width:' + size + 'px;height:' + size + 'px;line-height:' + size + 'px;'
                + 'background:' + colors[i] + ';color:' + text + ';border-radius:50%;'
                + 'border:2px solid rgba(255,255,255,0.85);box-shadow:0 1px 4px rgba(0,0,0,0.35);'
                + 'text-align:center;font:600 12px/' + size + 'px sans-serif;">' + n + '</div>',
            className: 'mako-cluster',
            iconSize: L.point(size, size)
        }});
    }}"""


def cluster_legend_html(max_count):
    stops = ", ".join(MAKO)
    return f"""
    <div style="position:absolute;bottom:24px;left:10px;z-index:1000;background:rgba(255,255,255,0.92);
                padding:6px 10px;border-radius:6px;box-shadow:0 1px 4px rgba(0,0,0,0.25);
                font:12px sans-serif;color:#333;">
      <div style="font-weight:600;margin-bottom:4px;">Libraries per cluster</div>
      <div style="width:160px;height:10px;border-radius:2px;background:linear-gradient(to right, {stops});"></div>
      <div style="display:flex;justify-content:space-between;width:160px;"><span>1</span><span>{max_count}</span></div>
    </div>"""


class LockToWorld(MacroElement):
    """Stop panning past the world's edge, and don't let users zoom out far
    enough to see empty space around it (recomputed when the frame resizes).
    Added as a child of the map so its script runs after the map exists."""
    _template = Template("""
        {% macro script(this, kwargs) %}
        (function() {
            var map = {{ this._parent.get_name() }};
            var world = L.latLngBounds(""" + str(WORLD_BOUNDS) + """);
            function setMin() {
                var z = map.getBoundsZoom(world, true);
                map.setMinZoom(z);
                if (map.getZoom() < z) map.setZoom(z);
            }
            setMin();
            map.on('resize', setMin);
        })();
        {% endmacro %}
    """)


def distance_km(lat1, lon1, lat2, lon2):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = p2 - p1, math.radians(lon2 - lon1)
    h = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 6371 * 2 * math.asin(math.sqrt(h))


# ----------------------------------------------------------------------------
# UI
# ----------------------------------------------------------------------------
css = f"""
body {{ font-family: 'Source Sans 3', 'Helvetica Neue', Arial, sans-serif; }}
.bslib-sidebar-layout > .sidebar {{ background: #F5F6F8; border-right: 1px solid #D9DCE1; }}
.app-title {{ font-weight: 700; font-size: 1.35rem; color: {UCONN_NAVY}; margin: 0; }}
.app-sub {{ color: #5B6573; font-size: 0.9rem; margin-bottom: 0.75rem; }}
.stat-row {{ display: flex; gap: 1.25rem; margin-top: 0.5rem; }}
.stat b {{ display: block; font-size: 1.6rem; color: {UCONN_NAVY}; line-height: 1.1; }}
.stat span {{ font-size: 0.8rem; color: #5B6573; }}
.map-wrap {{ height: calc(100vh - 2rem); }}
.map-wrap iframe {{ width: 100%; height: 100%; border: 0; }}
"""

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.tags.p("UConn Library Partners", class_="app-title"),
        ui.tags.p(f"{len(partners)} partner libraries in {len(COUNTRIES)} countries", class_="app-sub"),

        ui.input_radio_buttons(
            "scope", "Show",
            {"all": "All locations", "continent": "Selected continents", "country": "Selected countries"},
            selected="all",
        ),
        ui.panel_conditional(
            "input.scope === 'continent'",
            ui.input_selectize(
                "continents", "Continents", choices=CONTINENT_CHOICES, multiple=True,
                options={"placeholder": "Choose one or more…", "plugins": ["remove_button"]},
            ),
        ),
        ui.panel_conditional(
            "input.scope === 'country'",
            ui.input_selectize(
                "countries", "Countries", choices=COUNTRY_CHOICES, multiple=True,
                options={"placeholder": "Choose one or more…", "plugins": ["remove_button"]},
            ),
        ),
        ui.hr(),
        ui.input_switch("flows", f"Radial flows to {HUB_NAME}", value=False),
        ui.panel_conditional(
            "input.flows",
            ui.input_slider("flow_weight", "Line weight", min=0.5, max=5, value=1.5, step=0.5),
        ),
        ui.input_switch("cluster", "Cluster nearby points", value=False),
        ui.input_select(
            "basemap", "Basemap",
            {"Esri.WorldGrayCanvas": "Light gray", "OpenStreetMap": "Street", "Esri.WorldImagery": "Satellite"},
        ),
        ui.hr(),
        ui.output_ui("stats"),
        ui.download_button("download", "Download filtered CSV", class_="btn-sm btn-outline-secondary"),
        width=320,
    ),
    ui.div(ui.output_ui("map"), class_="map-wrap"),
    ui.tags.style(css),
    ui.head_content(ui.tags.link(
        rel="stylesheet",
        href="https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@400;600;700&display=swap",
    )),
    title="UConn Library Partner Map",
    fillable=True,
)


# ----------------------------------------------------------------------------
# SERVER
# ----------------------------------------------------------------------------
def server(input, output, session):

    @reactive.calc
    def filtered():
        scope = input.scope()
        if scope == "all":
            return partners
        col, chosen = ("continent_", input.continents()) if scope == "continent" else ("country_", input.countries())
        return partners[partners[col].isin(chosen or [])]

    @render.ui
    def stats():
        df = filtered()
        n_countries = df["country_"].nunique()
        if len(df):
            dists = [distance_km(r.lat_, r.lon_, HUB_LAT, HUB_LON) for r in df.itertuples()]
            avg = f"{sum(dists) / len(dists):,.0f}"
        else:
            avg = "–"
        return ui.div(
            ui.div(
                ui.div(ui.tags.b(len(df)), ui.tags.span("libraries"), class_="stat"),
                ui.div(ui.tags.b(n_countries), ui.tags.span("countries"), class_="stat"),
                ui.div(ui.tags.b(avg), ui.tags.span("avg km to Storrs"), class_="stat"),
                class_="stat-row",
            ),
            style="margin-bottom: 1rem;",
        )

    @render.ui
    def map():
        df = filtered()
        m = folium.Map(location=[30, HUB_LON], zoom_start=2, tiles=None, control_scale=True,
                       max_bounds=True, min_lat=WORLD_BOUNDS[0][0], max_lat=WORLD_BOUNDS[1][0],
                       min_lon=WORLD_BOUNDS[0][1], max_lon=WORLD_BOUNDS[1][1],
                       max_bounds_viscosity=1.0, zoom_snap=0.25, world_copy_jump=False)
        folium.TileLayer(input.basemap(), control=False).add_to(m)

        # Radial flow lines (drawn first so points sit on top)
        if input.flows() and len(df):
            flow_layer = folium.FeatureGroup(name="Flows to UConn Storrs")
            for r in df.itertuples():
                tip = f"{r.name_} → {HUB_NAME} ({distance_km(r.lat_, r.lon_, HUB_LAT, HUB_LON):,.0f} km)"
                for seg in great_circle(r.lat_, r.lon_, HUB_LAT, HUB_LON):
                    if len(seg) < 2:
                        continue
                    folium.PolyLine(seg, color=FLOW_COLOR, weight=input.flow_weight(),
                                    opacity=FLOW_OPACITY, tooltip=tip).add_to(flow_layer)
            flow_layer.add_to(m)

        # Partner points
        if input.cluster():
            point_layer = MarkerCluster(name="Partners", icon_create_function=cluster_icon_js(len(df)))
            if len(df):
                m.get_root().html.add_child(folium.Element(cluster_legend_html(len(df))))
        else:
            point_layer = folium.FeatureGroup(name="Partners")
        for r in df.itertuples():
            folium.CircleMarker(
                location=[r.lat_, r.lon_], radius=5, color="white", weight=1,
                fill=True, fill_color=POINT_COLOR, fill_opacity=0.9,
                tooltip=r.name_,
                popup=folium.Popup(f"<b>{r.name_}</b><br>{r.country_}", max_width=250),
            ).add_to(point_layer)
        point_layer.add_to(m)

        # UConn Storrs hub
        folium.Marker(
            [HUB_LAT, HUB_LON], tooltip=HUB_NAME,
            popup=f"<b>{HUB_NAME}</b><br>University of Connecticut",
            icon=folium.Icon(color="darkblue", icon="star", prefix="fa"),
        ).add_to(m)

        # Zoom to what's displayed
        if len(df):
            lats = list(df["lat_"]) + ([HUB_LAT] if input.flows() else [])
            lons = list(df["lon_"]) + ([HUB_LON] if input.flows() else [])
            if len(lats) > 1:
                m.fit_bounds([[min(lats), min(lons)], [max(lats), max(lons)]], padding=(30, 30))
            else:
                m.location, m.zoom_start = [lats[0], lons[0]], 6

        folium.LayerControl(collapsed=True).add_to(m)
        LockToWorld().add_to(m)

        # Embed as an iframe so Leaflet's JS runs cleanly inside Shiny
        return ui.tags.iframe(srcdoc=m.get_root().render(), style="width:100%;height:100%;border:0;")

    @render.download(filename="partners_filtered.csv")
    def download():
        df = filtered().drop(columns=["name_", "country_", "continent_", "lat_", "lon_"])
        yield df.to_csv(index=False)


app = App(app_ui, server)
